// Verified Revenue Bookkeeping Agent
// Tracks verified provider data only. This workflow does not provide tax, legal, or financial advice.

const financialConfig = {
  revenue_sources: {
    membership: {
      enabled: $env.MEMBERSHIP_ENABLED === 'true',
      provider: $env.MEMBERSHIP_PROVIDER,
      bookkeepingCategory: 'membership_income_after_approval'
    },
    shopify: {
      enabled: $env.SHOPIFY_ENABLED === 'true',
      apiKey: $env.SHOPIFY_API_KEY,
      shopDomain: $env.SHOPIFY_SHOP_DOMAIN,
      accessToken: $env.SHOPIFY_ACCESS_TOKEN,
      bookkeepingCategory: 'product_sales'
    },
    printify: {
      enabled: $env.PRINTIFY_ENABLED === 'true',
      apiKey: $env.PRINTIFY_API_KEY,
      shopId: $env.PRINTIFY_SHOP_ID,
      bookkeepingCategory: 'product_sales'
    },
    youtube: {
      enabled: $env.YOUTUBE_MONETIZATION_ENABLED === 'true',
      apiKey: $env.YOUTUBE_API_KEY,
      bookkeepingCategory: 'platform_revenue_after_monetization_verification'
    },
    affiliates: {
      enabled: $env.AFFILIATE_TRACKING_ENABLED === 'true',
      networks: {
        amazon: { enabled: Boolean($env.AMAZON_AFFILIATE_TAG), tag: $env.AMAZON_AFFILIATE_TAG },
        booking: { enabled: Boolean($env.BOOKING_AFFILIATE_ID), id: $env.BOOKING_AFFILIATE_ID },
        worldnomads: { enabled: Boolean($env.WORLDNOMADS_AFFILIATE_ID), id: $env.WORLDNOMADS_AFFILIATE_ID }
      },
      bookkeepingCategory: 'affiliate_commissions_after_enrollment_verification'
    },
    stripe: {
      enabled: $env.STRIPE_ENABLED === 'true',
      apiKey: $env.STRIPE_API_KEY,
      bookkeepingCategory: 'payment_processing'
    },
    paypal: {
      enabled: $env.PAYPAL_ENABLED === 'true',
      clientId: $env.PAYPAL_CLIENT_ID,
      clientSecret: $env.PAYPAL_CLIENT_SECRET,
      accessToken: $env.PAYPAL_ACCESS_TOKEN,
      bookkeepingCategory: 'payment_processing'
    }
  },

  expense_categories: {
    business_operations: ['software_subscriptions', 'hosting', 'domain_names', 'api_costs'],
    content_creation: ['equipment', 'editing_software', 'stock_photos', 'music_licensing'],
    marketing: ['advertising_after_approval', 'promotional_materials'],
    travel: ['flights', 'accommodation', 'meals', 'transportation'],
    professional_services: ['accounting', 'legal', 'consulting', 'freelancers']
  },

  review_policy: {
    record_only_verified_provider_revenue: true,
    tax_advice_allowed: false,
    purchase_or_payment_allowed: false,
    tax_review_required_by_human: true
  },

  tracking_periods: {
    daily: new Date().toISOString().split('T')[0],
    weekly: getWeekRange(),
    monthly: getMonthRange(),
    quarterly: getQuarterRange(),
    yearly: getYearRange()
  }
};

function getWeekRange() {
  const now = new Date();
  const startOfWeek = new Date(now);
  startOfWeek.setDate(now.getDate() - now.getDay());
  const endOfWeek = new Date(startOfWeek);
  endOfWeek.setDate(startOfWeek.getDate() + 6);
  return { start: startOfWeek.toISOString().split('T')[0], end: endOfWeek.toISOString().split('T')[0] };
}

function getMonthRange() {
  const now = new Date();
  const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
  const endOfMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0);
  return { start: startOfMonth.toISOString().split('T')[0], end: endOfMonth.toISOString().split('T')[0] };
}

function getQuarterRange() {
  const now = new Date();
  const quarter = Math.floor(now.getMonth() / 3);
  const startOfQuarter = new Date(now.getFullYear(), quarter * 3, 1);
  const endOfQuarter = new Date(now.getFullYear(), quarter * 3 + 3, 0);
  return { start: startOfQuarter.toISOString().split('T')[0], end: endOfQuarter.toISOString().split('T')[0] };
}

function getYearRange() {
  const now = new Date();
  const startOfYear = new Date(now.getFullYear(), 0, 1);
  const endOfYear = new Date(now.getFullYear(), 11, 31);
  return { start: startOfYear.toISOString().split('T')[0], end: endOfYear.toISOString().split('T')[0] };
}

return {
  financialConfig,
  analysisTimestamp: new Date().toISOString(),
  enabledSources: Object.keys(financialConfig.revenue_sources).filter(
    source => financialConfig.revenue_sources[source].enabled
  )
};

// Configure verified revenue source data collection
const financialData = $('Prepare Financial Analysis').first();
const currentSource = financialData.enabledSources[$('Process Each Revenue Source').itemIndex];

if (!currentSource) {
  return null;
}

const sourceConfig = financialData.financialConfig.revenue_sources[currentSource];
const trackingPeriods = financialData.financialConfig.tracking_periods;

function getShopifyFinancialConfig(config, periods) {
  return {
    source: 'shopify',
    apiUrl: config.shopDomain ? 'https://' + config.shopDomain + '.myshopify.com/admin/api/2023-10/orders.json' : null,
    headers: { 'X-Shopify-Access-Token': config.accessToken || config.apiKey },
    params: {
      'created_at_min': periods.monthly.start + 'T00:00:00Z',
      'created_at_max': periods.monthly.end + 'T23:59:59Z',
      'financial_status': 'paid',
      'limit': 250
    },
    bookkeepingCategory: config.bookkeepingCategory,
    revenueType: 'one_time'
  };
}

function getStripeFinancialConfig(config, periods) {
  return {
    source: 'stripe',
    apiUrl: 'https://api.stripe.com/v1/charges',
    headers: { 'Authorization': 'Bearer ' + config.apiKey },
    params: {
      'created[gte]': Math.floor(new Date(periods.monthly.start).getTime() / 1000),
      'created[lte]': Math.floor(new Date(periods.monthly.end).getTime() / 1000),
      'limit': 100
    },
    bookkeepingCategory: config.bookkeepingCategory,
    revenueType: 'payment_processing'
  };
}

function getPayPalFinancialConfig(config, periods) {
  return {
    source: 'paypal',
    apiUrl: 'https://api.paypal.com/v1/reporting/transactions',
    headers: {
      'Authorization': 'Bearer ' + config.accessToken,
      'Content-Type': 'application/json'
    },
    params: {
      'start_date': periods.monthly.start + 'T00:00:00Z',
      'end_date': periods.monthly.end + 'T23:59:59Z',
      'fields': 'all',
      'page_size': 500
    },
    bookkeepingCategory: config.bookkeepingCategory,
    revenueType: 'payment_processing'
  };
}

let apiConfig;
switch (currentSource) {
  case 'shopify':
    apiConfig = getShopifyFinancialConfig(sourceConfig, trackingPeriods);
    break;
  case 'stripe':
    apiConfig = getStripeFinancialConfig(sourceConfig, trackingPeriods);
    break;
  case 'paypal':
    apiConfig = getPayPalFinancialConfig(sourceConfig, trackingPeriods);
    break;
  default:
    apiConfig = {
      source: currentSource,
      manual_tracking: true,
      apiUrl: null,
      headers: {},
      params: {},
      bookkeepingCategory: sourceConfig.bookkeepingCategory,
      revenueType: 'manual_verified_entry'
    };
}

return {
  ...apiConfig,
  trackingPeriods,
  reviewPolicy: financialData.financialConfig.review_policy,
  analysisTimestamp: financialData.analysisTimestamp
};

// Process provider data as verified bookkeeping records only
const apiResponse = $input.first();
const sourceConfig = $('Configure Revenue Tracking').first();

function processShopifyRevenue(data) {
  const orders = data.orders || [];
  const paidOrders = orders.filter(order => !order.financial_status || order.financial_status === 'paid');
  const totalRevenue = paidOrders.reduce((sum, order) => sum + parseFloat(order.total_price || 0), 0);
  const totalTax = paidOrders.reduce((sum, order) => sum + parseFloat(order.total_tax || 0), 0);
  return {
    gross_revenue: totalRevenue,
    net_revenue: totalRevenue - totalTax,
    transaction_count: paidOrders.length,
    average_transaction: paidOrders.length > 0 ? totalRevenue / paidOrders.length : 0,
    revenue_type: 'product_sales',
    taxes_collected: totalTax,
    processing_fees: 0,
    note: 'Fees/taxes require provider reconciliation before public reporting.'
  };
}

function processStripeRevenue(data) {
  const charges = data.data || [];
  const successfulCharges = charges.filter(charge => charge.status === 'succeeded');
  const totalRevenue = successfulCharges.reduce((sum, charge) => sum + (charge.amount / 100), 0);
  return {
    gross_revenue: totalRevenue,
    net_revenue: totalRevenue,
    transaction_count: successfulCharges.length,
    average_transaction: successfulCharges.length > 0 ? totalRevenue / successfulCharges.length : 0,
    revenue_type: 'payment_processing',
    processing_fees: 0,
    note: 'Payment fees require provider reconciliation before public reporting.'
  };
}

function processPayPalRevenue(data) {
  const transactions = data.transaction_details || [];
  const revenueTransactions = transactions.filter(t =>
    t.transaction_info?.transaction_status === 'S' &&
    parseFloat(t.transaction_info?.transaction_amount?.value || 0) > 0
  );
  const totalRevenue = revenueTransactions.reduce((sum, transaction) =>
    sum + parseFloat(transaction.transaction_info?.transaction_amount?.value || 0), 0
  );
  return {
    gross_revenue: totalRevenue,
    net_revenue: totalRevenue,
    transaction_count: revenueTransactions.length,
    average_transaction: revenueTransactions.length > 0 ? totalRevenue / revenueTransactions.length : 0,
    revenue_type: 'payment_processing',
    processing_fees: 0,
    note: 'Payment fees require provider reconciliation before public reporting.'
  };
}

let revenueData;
switch (sourceConfig.source) {
  case 'shopify':
    revenueData = processShopifyRevenue(apiResponse);
    break;
  case 'stripe':
    revenueData = processStripeRevenue(apiResponse);
    break;
  case 'paypal':
    revenueData = processPayPalRevenue(apiResponse);
    break;
  default:
    revenueData = { gross_revenue: 0, net_revenue: 0, transaction_count: 0, revenue_type: 'manual_verified_entry_required' };
}

return {
  source: sourceConfig.source,
  bookkeeping_category: sourceConfig.bookkeepingCategory,
  revenue_data: revenueData,
  tax_calculations: {
    gross_revenue: revenueData.gross_revenue || 0,
    net_revenue: revenueData.net_revenue || revenueData.gross_revenue || 0,
    estimated_income_tax: 0,
    estimated_self_employment_tax: 0,
    total_estimated_tax: 0,
    quarterly_payment: 0,
    should_make_quarterly_payment: false,
    status: 'human_tax_professional_review_required'
  },
  tracking_period: sourceConfig.trackingPeriods.monthly,
  analysis_timestamp: sourceConfig.analysisTimestamp
};

// Compile verified bookkeeping report. Not tax, legal, or financial advice.
const allRevenueData = $input.all();

const revenueBySource = {};
const revenueByCategory = {};
let totalGrossRevenue = 0;
let totalNetRevenue = 0;

allRevenueData.forEach(sourceData => {
  if (sourceData.revenue_data) {
    const source = sourceData.source;
    const category = sourceData.bookkeeping_category || sourceData.tax_category || 'uncategorized';
    const revenueData = sourceData.revenue_data;

    revenueBySource[source] = {
      gross_revenue: revenueData.gross_revenue || 0,
      net_revenue: revenueData.net_revenue || revenueData.gross_revenue || 0,
      transaction_count: revenueData.transaction_count || 0,
      processing_fees: revenueData.processing_fees || 0
    };

    if (!revenueByCategory[category]) {
      revenueByCategory[category] = { gross_revenue: 0, net_revenue: 0 };
    }

    revenueByCategory[category].gross_revenue += revenueData.gross_revenue || 0;
    revenueByCategory[category].net_revenue += revenueData.net_revenue || revenueData.gross_revenue || 0;
    totalGrossRevenue += revenueData.gross_revenue || 0;
    totalNetRevenue += revenueData.net_revenue || revenueData.gross_revenue || 0;
  }
});

const profitMargin = totalGrossRevenue > 0 ? (totalNetRevenue / totalGrossRevenue) * 100 : 0;
const topRevenueSource = Object.entries(revenueBySource)
  .sort(([, a], [, b]) => b.gross_revenue - a.gross_revenue)[0]?.[0] || 'none';

const insights = [];
const recommendations = [];

if (totalGrossRevenue > 0) {
  insights.push('Verified provider revenue was found for the selected period.');
  recommendations.push('Reconcile provider fees, refunds, taxes, and shipping before reporting profit.');
} else {
  insights.push('No verified provider revenue found for this period.');
  recommendations.push('Keep revenue at $0 until store, affiliate, platform, or payment-provider data verifies it.');
}

recommendations.push('Have Daniel or a qualified professional review tax obligations before any payment decision.');

return {
  overview: {
    total_gross_revenue: totalGrossRevenue,
    total_net_revenue: totalNetRevenue,
    total_estimated_tax: 0,
    cash_flow_after_tax: totalNetRevenue,
    profit_margin: profitMargin,
    effective_tax_rate: 0,
    top_revenue_source: topRevenueSource,
    provider_verified_only: true
  },
  revenue_breakdown: {
    by_source: revenueBySource,
    by_category: revenueByCategory
  },
  tax_obligations: {
    quarterly_payment_due: 0,
    payment_required: false,
    next_due_date: null,
    days_until_due: null,
    status: 'not_calculated_human_professional_review_required'
  },
  insights,
  recommendations,
  tracking_period: allRevenueData[0]?.tracking_period || null,
  analysis_timestamp: new Date().toISOString()
};

